validator:
function validate(input) {
  const [{ Products = [] }] = input;
  const ids = new Set();
  for (const [id] of Products) {
    if (id === null) return 'Every product needs a product_id.';
    if (ids.has(id)) return `product_id ${id} appears twice in Products.`;
    ids.add(id);
  }
  return null;
}

generator:
function generate(rand, size) {
  const small = size === 'small';
  const prices = [0, 5, 70, 80, 95, 100, 105];
  const count = small ? Math.floor(rand() * 9) : 2000;
  // Small cases reuse a few prices and often leave stores empty; some products carry nothing at all.
  const nullChance = small ? [0.15, 0.35, 0.6, 1][Math.floor(rand() * 4)] : 0.3;
  const price = () => rand() < nullChance ? null : small ? prices[Math.floor(rand() * prices.length)] : Math.floor(rand() * 1000);
  const Products = [];
  let id = small ? Math.floor(rand() * 3) : 1;
  for (let i = 0; i < count; i++) {
    Products.push([id, price(), price(), price()]);
    id += small ? 1 + Math.floor(rand() * 3) : 1;
  }
  return [{ Products }];
}
